/* kat_vectors.c — drive liboqs with the official .rsp inputs directly.
 *
 * The liboqs kat_kem/kat_sig programs use the PQC-submission-era NIST
 * AES-256-CTR-DRBG KAT procedure, while the .rsp files in work/kat are the
 * FIPS 203/204 deterministic KATs generated by a different procedure, so a
 * straight kat_kem-vs-.rsp comparison fails at the seed itself. This helper
 * answers the sharper question: fed the .rsp's own d/z/msg inputs through
 * the public derand API, does liboqs reproduce the .rsp pk/sk/ct/ss?
 *
 * Usage:
 *   kat_vectors ML-KEM-768 <keypair_seed_hex: d||z, 64 bytes> <encaps_seed_hex: msg, 32 bytes>
 * Prints: pk, sk, ct, ss (hex), plus decaps ss match (yes/no).
 *
 * Build (from the pack root):
 *   cc -O2 -std=c11 -Iwork/liboqs/build/include -o work/measure/kat_vectors \
 *      work/measure/kat_vectors.c work/liboqs/build/lib/liboqs.a -lcrypto -lm
 */
#include <oqs/oqs.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int hexval(int c) {
	if (c >= '0' && c <= '9') { return c - '0'; }
	if (c >= 'a' && c <= 'f') { return c - 'a' + 10; }
	if (c >= 'A' && c <= 'F') { return c - 'A' + 10; }
	return -1;
}

static int unhex(const char *hex, uint8_t *out, size_t outlen) {
	if (strlen(hex) != outlen * 2) { return -1; }
	for (size_t i = 0; i < outlen; i++) {
		int hi = hexval(hex[2 * i]), lo = hexval(hex[2 * i + 1]);
		if (hi < 0 || lo < 0) { return -1; }
		out[i] = (uint8_t)((hi << 4) | lo);
	}
	return 0;
}

static void printhex(const char *label, const uint8_t *buf, size_t len) {
	printf("%s = ", label);
	for (size_t i = 0; i < len; i++) { printf("%02x", buf[i]); }
	printf("\n");
}

int main(int argc, char **argv) {
	if (argc != 4) {
		fprintf(stderr, "usage: %s ALG keypair_seed_hex encaps_seed_hex\n", argv[0]);
		return 2;
	}
	OQS_init();
	OQS_KEM *kem = OQS_KEM_new(argv[1]);
	if (!kem) { fprintf(stderr, "alg not enabled\n"); return 1; }
	uint8_t *kp_seed = malloc(kem->length_keypair_seed);
	uint8_t *enc_seed = malloc(kem->length_encaps_seed);
	uint8_t *pk = malloc(kem->length_public_key);
	uint8_t *sk = malloc(kem->length_secret_key);
	uint8_t *ct = malloc(kem->length_ciphertext);
	uint8_t *ss = malloc(kem->length_shared_secret);
	uint8_t *ss_d = malloc(kem->length_shared_secret);
	if (!kp_seed || !enc_seed || !pk || !sk || !ct || !ss || !ss_d) { fprintf(stderr, "malloc failed\n"); return 1; }
	if (unhex(argv[2], kp_seed, kem->length_keypair_seed) != 0 ||
	    unhex(argv[3], enc_seed, kem->length_encaps_seed) != 0) {
		fprintf(stderr, "bad hex input (want %zu + %zu bytes)\n",
		        kem->length_keypair_seed, kem->length_encaps_seed);
		return 2;
	}
	if (OQS_KEM_keypair_derand(kem, pk, sk, kp_seed) != OQS_SUCCESS) { fprintf(stderr, "keypair failed\n"); return 1; }
	if (OQS_KEM_encaps_derand(kem, ct, ss, pk, enc_seed) != OQS_SUCCESS) { fprintf(stderr, "encaps failed\n"); return 1; }
	printhex("pk", pk, kem->length_public_key);
	printhex("sk", sk, kem->length_secret_key);
	printhex("ct", ct, kem->length_ciphertext);
	printhex("ss", ss, kem->length_shared_secret);
	OQS_STATUS rc = OQS_KEM_decaps(kem, ss_d, ct, sk);
	printf("decaps_ss_match = %s\n", (rc == OQS_SUCCESS && memcmp(ss, ss_d, kem->length_shared_secret) == 0) ? "yes" : "no");
	free(kp_seed); free(enc_seed); free(pk); free(sk); free(ct); free(ss); free(ss_d);
	OQS_KEM_free(kem);
	OQS_destroy();
	return 0;
}
